                              \begin{tikzpicture}[scale=3]
                                \clip (-0.1,-0.2) rectangle (1.1,0.75);
                                \draw[step=.5cm,gray,very thin] (-1.4,-1.4) grid (1.4,1.4);
                                \draw (-1.5,0) -- (1.5,0);
                                \draw (0,-1.5) -- (0,1.5);
                                \draw (0,0) circle [radius=1cm];
