                                     \draw[->] (-1.5,0) -- (1.5,0);   \draw[->] (0,-1.5) -- (0,1.5);
                                     \draw (0,0) circle [radius=1cm];

                                     \foreach \x in {-1,-0.5,1}
                0.5                    \draw (\x cm,1pt) -- (\x cm,-1pt) node[anchor=north] {$\x$};
