                                  edge [pre]                                 (critical)
                                  edge [post,bend right] node[auto,swap] {2} (waiting)
                                  edge [pre, bend left]                      (semaphore);
                                \node[transition] (enter critical) [left=of critical] {}
                                  edge [post]                                (critical)
                                  edge [pre, bend left]                      (waiting)
                                  edge [post,bend right]                     (semaphore);
