                                  edge [post]                                (critical)
                                  edge [pre, bend left]                      (waiting)
                                  edge [post,bend right]                     (semaphore);

                                \begin{scope}[on background layer]
                                  \node [fill=black!30,fit=(waiting) (critical) (semaphore)
                                           (leave critical) (enter critical)] {};
