\begin{tikzpicture}[line width=10pt]
       \draw (0,0) -- (1,1) -- (1,0) -- (0,0) (2,0) -- (3,1) -- (3,0) -- (2,0);
       \draw (5,0) -- (6,1) -- (6,0) -- cycle (7,0) -- (8,1) -- (8,0) -- cycle;
       \useasboundingbox (0,1.5); % make bounding box higher
