                       a         \usetikzlibrary {graphs,graphdrawing}\usegdlibrary {layered}
                                 \tikz \graph [trie, simple, layered layout,
                                               typeset=\tikzgraphnodefullname] {
             ab        ad   aa     a -> b -> a,
                                   a -> b -> c,
                                   a -> {d,a}
