                 \draw[->] (0,-1.2) -- (0,4.2) node[above] {$f(x)$};

              \draw[red,label={[above left]{$f(x)=x$}}]                       plot (\x,\x);
              \draw[blue,label={[below left]{$f(x)=\sin x$}}]                 plot (\x,{sin(\x r)});
              \draw[orange,label={[right]{$f(x)= \frac{1}{20} \mathrm e^x$}}] plot (\x,{0.05*exp(\x)});
