                                \node[place,label=below:$p_2\ge1$,right=of p1] (p2) {};
                    p2 ≥ 1    \end{tikzpicture}

     /tikz/every place                                                                       (style, no value)
         This style is evoked by the style place. To change the appearance of places, you can change this
         style.

