                                                 fill=blue!20,draw=blue,thick]
                                  {Hello World!};
             Hello World!
                                \node at (0,-2) [copy shadow={opacity=.5},tape,
                                                 fill=blue!20,draw=blue,thick]
             Hello World!         {Hello World!};

                                % We have to repeat the left color since shadings are not
                                % automatically applied to shadows
