                                         \pgfusepath{stroke}
              0.5                        \foreach \t in {0,0.25,...,1.25}
          0.25                             {\pgftext[at=
                                             \pgfpointlineattime{\t}{\pgfpointorigin}{\pgfpoint{2cm}{2cm}}]{\t}}
      0                                \end{tikzpicture}

