               foo              \draw [help lines] (0,0) grid (3,2);
                                \pgftransformnonlinear{\polartransformation}% see above
                                \draw (0pt,0mm) grid [xstep=10pt, ystep=5mm] (90pt, 20mm);

                                \begin{scope}[shift={(45pt,20mm)}]
                                  % Draw something near "origin":
