    f         f     f   f
         f                     \foreach \t in {0,1,2,3,4} {
                                 \pgfsnapshot{\t}
                                 \tikz :rotate = { 0s = "0", 2s = "90", 2s = "180", 4s = "270" }
                                   \node [draw=blue, very thick] {f}; }

                               \usepgfmodule {animations}
